CREATE TABLE "public"."acessos" (
  "id_acesso"  integer                     GENERATED ALWAYS AS IDENTITY NOT NULL,
  "id_tag"     integer                     NOT NULL,
  "data_hora"  timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "id_usuario" smallint,
  CONSTRAINT "acessos_pkey" PRIMARY KEY (id_acesso)
);

ALTER TABLE "public"."acessos"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."alertas" (
  "id_alerta"   integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_usuario"  integer                     NOT NULL,
  "tipo_alerta" character varying(50),
  "data_hora"   timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "imagem_url"  text,
  CONSTRAINT "alertas_pkey" PRIMARY KEY (id_alerta)
);

ALTER TABLE "public"."alertas"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."cameras" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "data_hora"    timestamp with time zone NOT NULL DEFAULT now(),
  "endereco"     text,
  "status"       text,
  "nome_usuario" text,
  "id_usuario"   integer,
  CONSTRAINT "cameras_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."cameras"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."codigo_verificacao" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "email"      text                     NOT NULL,
  "codigo"     text                     NOT NULL,
  "expira_em"  timestamp with time zone NOT NULL,
  "verificado" boolean                  NOT NULL DEFAULT false,
  "criado_em"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "codigo_verificacao_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."codigo_verificacao"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."contatos_emergencia" (
  "id_contato"       integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "data_criacao"     timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
  "id_usuario"       integer,
  "nome_contato"     character varying(100),
  "telefone_contato" character varying(20),
  CONSTRAINT "contatos_emergencia_pkey" PRIMARY KEY (id_contato)
);

ALTER TABLE "public"."contatos_emergencia"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."fechaduras" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "mac_address" character varying,
  "id_usuario"  integer,
  "status"      text,
  "data_hora"   timestamp with time zone NOT NULL DEFAULT now(),
  "blocked"     boolean,
  CONSTRAINT "fechaduras_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."fechaduras"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."nfc_tags" (
  "id_tag"       integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_usuario"   integer                     NOT NULL,
  "uid_nfc"      character varying(255)      NOT NULL,
  "data_hora"    timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "id_fechadura" bigint,
  "nome_tag"     text,
  CONSTRAINT "nfc_tags_pkey" PRIMARY KEY (id_tag),
  CONSTRAINT "nfc_tags_uid_nfc_key" UNIQUE (uid_nfc)
);

ALTER TABLE "public"."nfc_tags"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."portas" (
  "id_porta" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CONSTRAINT "portas_pkey" PRIMARY KEY (id_porta)
);

ALTER TABLE "public"."portas"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."reset_password" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "id_usuario" integer,
  "token_hash" text                     NOT NULL,
  "expira_em"  timestamp with time zone NOT NULL,
  "criado_em"  timestamp with time zone DEFAULT now(),
  CONSTRAINT "reset_password_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."reset_password"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sensor" (
  "id_sensor" integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_porta"  integer                     NOT NULL,
  "data_hora" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "sensor_pkey" PRIMARY KEY (id_sensor)
);

ALTER TABLE "public"."sensor"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."usuario" (
  "id_usuario"      integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome_usuario"    character varying(30)       NOT NULL,
  "email_usuario"   character varying(50)       NOT NULL,
  "senha_usuario"   character varying(70)       NOT NULL,
  "data_criacao"    timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
  "versao_adaptada" boolean,
  "admin"           boolean                     DEFAULT false,
  CONSTRAINT "usuario_email_usuario_key" UNIQUE (email_usuario),
  CONSTRAINT "usuario_pkey" PRIMARY KEY (id_usuario)
);

ALTER TABLE "public"."usuario"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."acesso_estado" AS ENUM (
  'PERMITIDO',
  'NEGADO'
);

CREATE TYPE "public"."alerta_tipo" AS ENUM (
  'ACESSONEGADO',
  'INCÊNDIO',
  'FECHADURANOVA'
);

CREATE TYPE "public"."status_porta" AS ENUM (
  'ABERTO',
  'FECHADO'
);

ALTER TABLE "public"."portas"
  ADD COLUMN "status_porta" public.status_porta NOT NULL;

CREATE TYPE "public"."tipo_sensor" AS ENUM (
  'VIBRAÇÃO',
  'FUMAÇA'
);

ALTER TABLE "public"."sensor"
  ADD COLUMN "tipo_sensor" public.tipo_sensor NOT NULL;

ALTER TABLE "public"."cameras"
  ADD CONSTRAINT "cameras_id_usuario_fkey" FOREIGN KEY (id_usuario) REFERENCES public.usuario(id_usuario);

ALTER TABLE "public"."fechaduras"
  ADD CONSTRAINT "fechaduras_id_usuario_fkey" FOREIGN KEY (id_usuario) REFERENCES public.usuario(id_usuario);

ALTER TABLE "public"."reset_password"
  ADD CONSTRAINT "reset_password_id_usuario_fkey" FOREIGN KEY (id_usuario) REFERENCES public.usuario(id_usuario) ON DELETE CASCADE;

CREATE INDEX idx_codigo_verificacao_email ON public.codigo_verificacao USING btree (email);

CREATE POLICY "insert" ON "public"."acessos"
  FOR INSERT
  TO PUBLIC
  WITH CHECK (true);

CREATE POLICY "select" ON "public"."acessos"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "insert" ON "public"."alertas"
  FOR INSERT
  TO PUBLIC
  WITH CHECK (true);

CREATE POLICY "select" ON "public"."alertas"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Permitir leitura de fechaduras" ON "public"."fechaduras"
  FOR SELECT
  TO "anon"
  USING (true);

CREATE POLICY "Permitir insercao de tags" ON "public"."nfc_tags"
  FOR INSERT
  TO "anon"
  WITH CHECK (true);

CREATE POLICY "Permitir leitura de tags" ON "public"."nfc_tags"
  FOR SELECT
  TO "anon"
  USING (true);

